'use strict';
(()=>{
const path=location.pathname.replace(/\/+$/,'')||'/';
const finalImages={'Black London':'/assets/spray-products-final/black-london-new.png','Sweet Rose':'/assets/spray-products-final/sweet-rose-new.png','Velvet Night':'/assets/spray-products-final/velvet-night-new.png','Machmoun':'/assets/spray-products-final/machmoun-new.png','Cotton Candy':'/assets/spray-products-final/cotton-candy-new.png','بلاك لندن':'/assets/spray-products-final/black-london-new.png','سويت روز':'/assets/spray-products-final/sweet-rose-new.png','فيلفت نايت':'/assets/spray-products-final/velvet-night-new.png','المشموم':'/assets/spray-products-final/machmoun-new.png','كوتن كاندي':'/assets/spray-products-final/cotton-candy-new.png'};
const homeStyle=document.createElement('style');homeStyle.textContent=`@media(min-width:701px){#bakhoor-products{display:grid!important;grid-template-columns:repeat(4,minmax(0,1fr))!important;gap:25px!important;max-width:none!important}#bakhoor-products .product-card{min-width:0!important;width:auto!important}}@media(max-width:700px){#bakhoor-products{display:flex!important;gap:14px!important;overflow-x:auto!important;scroll-snap-type:x mandatory!important;-webkit-overflow-scrolling:touch!important}#bakhoor-products .product-card{flex:0 0 clamp(245px,72vw,330px)!important;scroll-snap-align:start!important}}`;document.head.appendChild(homeStyle);
function fixHome(){const grid=document.querySelector('#home-products');if(grid)grid.querySelectorAll('.product-card').forEach(card=>{const title=(card.querySelector('h3')?.textContent||'').trim();const img=card.querySelector('img');const src=finalImages[title];if(src&&img&&img.getAttribute('src')!==src){img.src=src;img.removeAttribute('srcset');}});const privateGrid=document.querySelector('#bakhoor-products');if(privateGrid&&typeof products!=='undefined'&&typeof card==='function'){const ids=['sultana-oud','royal-bukhoor','amber-night','oud-collection-set'];const html=ids.map(id=>products.find(p=>p.id===id)).filter(Boolean).map(card).join('');if(html&&privateGrid.querySelectorAll('.product-card').length!==4)privateGrid.innerHTML=html;}}
if(path!=='/room-sprays'){fixHome();const observer=new MutationObserver(fixHome);observer.observe(document.documentElement,{childList:true,subtree:true});return;}
const sprayIds=['black-london','sweet-rose','velvet-night','machmoun','cotton-candy','royal-fruity','wood-bouquet','my-mood','blanc-imperial'];
const sprayNames={'black-london':'Black London','sweet-rose':'Sweet Rose','velvet-night':'Velvet Night','machmoun':'Machmoun','cotton-candy':'Cotton Candy','royal-fruity':'Royal Fruity','wood-bouquet':'Wood Bouquet','my-mood':'My Mood','blanc-imperial':'Blanc Imperial'};
const css=document.createElement('style');css.textContent=`.spray-latest-hero{width:100%;aspect-ratio:3/1;overflow:hidden;background:#1c1712}.spray-latest-hero img{width:100%;height:100%;object-fit:cover;display:block}.spray-use-cards{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:16px!important}.spray-use-cards .category-card{position:relative;display:block;overflow:hidden;background:#eee;aspect-ratio:4/3!important;height:auto!important}.spray-use-cards .category-card:after{display:none!important}.spray-use-cards img{position:absolute!important;inset:0!important;width:100%!important;height:100%!important;max-width:none!important;object-fit:cover!important;object-position:center center!important;display:block!important;margin:0!important;transform:none!important}.spray-use-cards .category-card:hover img{transform:none!important}.spray-products-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:24px}.spray-product-card{border:1px solid #d8c4a6;padding:8px;text-align:center;background:#fff}.spray-product-card a{color:inherit;text-decoration:none}.spray-product-image{aspect-ratio:1/1;overflow:hidden;background:#f3eee5}.spray-product-image img{width:100%;height:100%;display:block;object-fit:cover}.spray-product-card h3{font-family:serif;font-size:26px;font-weight:400;margin:16px 5px 8px}.spray-product-card p{font-size:12px;letter-spacing:.04em;color:#756f68;margin:0 0 12px}.spray-product-card .price{font-size:15px;color:#1d1915;margin-bottom:16px}.spray-product-card .add-btn{display:block;margin:0 auto 10px;width:65%;padding:12px;border:1px solid #cdb18d;background:transparent;font-size:14px}.spray-latest-bottom{width:100%;overflow:hidden}.spray-latest-bottom img{display:block;width:100%;height:auto}@media(max-width:900px){.spray-products-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){.spray-latest-hero{aspect-ratio:1/1}.spray-use-cards{display:flex!important;overflow-x:auto!important;gap:12px!important;scroll-snap-type:x mandatory!important}.spray-use-cards .category-card{flex:0 0 82%!important;aspect-ratio:4/3!important;scroll-snap-align:start!important}.spray-products-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.spray-product-card h3{font-size:20px}.spray-product-card .add-btn{width:90%}}`;document.head.appendChild(css);
function productCard(id){const name=sprayNames[id];const img=`/assets/spray-products-final/${id}-new.png`;return `<article class="spray-product-card"><a href="/products/${id}/"><div class="spray-product-image"><img src="${img}" alt="${name} by Sultana" loading="lazy" onerror="this.onerror=null;this.src='/assets/products-square/${id}.webp'"></div><h3>${name}</h3></a><p>LUXURY HOME SPRAY · 300 ML</p><div class="price">QAR 120</div><button class="add-btn" type="button" data-product-id="${id}">ADD TO BAG</button></article>`}
function restore(){const main=document.querySelector('#main-content');if(!main||main.dataset.latestSpray==='2')return;main.dataset.latestSpray='2';main.innerHTML=`<section class="spray-latest-hero" aria-label="Luxury Spray Collection"><img src="/assets/ChatGPT%20Image%20Sep%2021%2C%202026%2C%2007_02_23%20PM.png" alt="The Ambiance Collection"></section><section class="section-shell department-categories"><div class="section-heading"><div><h2>One Mist. Many Moments.</h2></div><a class="text-link" href="#collection">View all</a></div><div class="category-section spray-use-cards"><a class="category-card" href="#collection"><img src="/assets/use-room-mist.png" alt="Room Mist"></a><a class="category-card" href="#collection"><img src="/assets/use-car-mist.png" alt="Car Mist"></a><a class="category-card" href="#collection"><img src="/assets/use-clothing-mist.png" alt="Clothing Mist"></a></div></section><section class="shop-section section-shell" id="collection"><div class="section-heading"><div><h2>The Ambiance Collection</h2></div></div><div class="spray-products-grid">${sprayIds.map(productCard).join('')}</div></section><section class="perfume-gift-banner spray-latest-bottom" id="spray-gift-banner"><a href="/shop/?collection=gift#collection"><img src="/assets/campaigns/spray-bottom-banner.webp" alt="Luxury Spray Gift Set" loading="lazy"></a></section>`;}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',restore,{once:true});else restore();setTimeout(restore,100);
})();
